// Le cadrage du dessin, et la part de la boîte qu'il occupe.
//
// Ces deux nombres vivent ICI, et pas dans `face-draw.jsx`, parce que la queue du
// cube doit savoir où poser le point blanc — donc connaître le repère du visage.
// `face-draw.jsx` les lit au lieu de les réécrire : si le dessin change de taille,
// le raccord se déplace tout seul au lieu de dériver en silence.
export const FACE_VIEWBOX = 280;
export const FACE_BOX = 0.78;

// Où la plume se pose : le premier `M` du premier trait.
//
// LU dans le chemin plutôt que recopié. Le nombre se voit dans la chaîne — et
// 170,37 / 89,09 se lirait comme une coordonnée en dur alors qu'elle n'en est
// pas une : elle se déplace si le premier trait du dessin change, et le point
// blanc doit suivre le trait, pas l'inverse.
export const FACE_START = (() => {
  const [x, y] = FACE_PATHS[0].slice(1).split("C")[0].split(",");
  return { x: Number(x), y: Number(y) };
})();
